<script setup>
import RecycleBin from "./RecycleBin.vue";
import {useUiText} from "../ui-text";
const ui=useUiText();

import {ref,onMounted} from 'vue';
import {RefreshCw,Trash2,LoaderCircle} from 'lucide-vue-next';
import {useStudio,api} from '../store';
const s=useStudio(),status=ref(null),busy=ref(false),error=ref(''),trash=ref({projects:[],images:[]}),trashMode=ref('');
s.config.cacheMaintenance||={enabled:true,maxMB:0,days:7};
const size=bytes=>bytes>=1024**3?(bytes/1024**3).toFixed(2)+' GB':(bytes/1024**2).toFixed(1)+' MB';
async function refresh(){busy.value=true;error.value='';try{[status.value,trash.value]=await Promise.all([api('cache/status'),api('trash')]);}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function clean(){busy.value=true;try{const result=await api('cache/clean',{});s.notify(result.skipped||`已清理 ${result.removedFiles} 个缓存文件，释放 ${size(result.removedBytes)}`);status.value=await api('cache/status');}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(refresh);
</script>
<template><section class="card"><div class="card-heading"><strong>{{ui("缓存与存储")}}</strong><button class="quiet" @click="refresh" :disabled="busy" :aria-busy="busy"><RefreshCw :size="15"/>{{ui("刷新占用")}}</button></div><div class="settings-body"><label class="inline-check"><input type="checkbox" v-model="s.config.cacheMaintenance.enabled"/>{{ui("空闲时自动清理临时缓存")}}</label><p class="muted">{{ui("启动后和每隔 30 分钟检查，按缓存期限与磁盘可用空间清理。")}}</p><p v-if="status">{{ui("临时缓存 ")}}{{ui(size(status.bytes))}}{{ui(" · 自动容量上限 ")}}{{ui(size(status.maxBytes))}}</p><p v-if="status?.last" class="muted">{{ui("上次释放 ")}}{{ui(size(status.last.removedBytes))}} · {{ui(new Date(status.last.at).toLocaleString())}}</p><p v-if="error" class="error-note">{{ui(error)}}</p><div class="button-row"><button class="secondary" @click="clean" :disabled="busy" :aria-busy="busy"><LoaderCircle v-if="busy" :size="15" class="spin"/><Trash2 v-else :size="15"/>{{ui("立即清理过期缓存")}}</button></div><p class="muted">{{ui("作品、模型、聊天、自动保存、登录状态及未完成下载会保留。")}}</p><details><summary>{{ui("高级：缓存期限和容量")}}</summary><div class="parameter-grid"><label>{{ui("保留天数")}}<input type="number" v-model.number="s.config.cacheMaintenance.days" min="1" max="30"/></label><label>{{ui("容量上限（MB，0 为自动）")}}<input type="number" v-model.number="s.config.cacheMaintenance.maxMB" min="0" max="8192"/></label></div></details></div></section><section class="card"><div class="card-heading"><strong>{{s.t('本地回收区','Local recycle bin')}}</strong></div><div class="settings-body"><p>{{s.t('已删除项目','Deleted projects')}} {{trash.projects.length}} · {{s.t('已删除图片','Deleted images')}} {{trash.images.length}}</p><p class="muted">{{s.t('回收内容保存在 works/trash，不会自动清理，也不会进入 Windows 回收站。可先恢复需要的内容，再永久清空。','Recycled content is stored in works/trash, separate from the Windows Recycle Bin. It is never cleared automatically. Restore anything you need before emptying it.')}}</p><div class="button-row"><button class="secondary" @click="trashMode='view'">{{s.t('查看回收区 / 恢复','View recycle bin / restore')}}</button><button class="secondary danger" :disabled="!(trash.projects.length+trash.images.length)" @click="trashMode='clear'"><Trash2 :size="15"/>{{s.t('一键清除回收区垃圾','Empty recycle bin')}}</button></div></div></section><RecycleBin v-if="trashMode" :clear-on-open="trashMode==='clear'" @close="trashMode='';s.action(refresh)" @changed="s.action(refresh)"/></template>
